<script setup>
import {computed,onMounted,onBeforeUnmount,ref} from 'vue';
import {ElMessage} from 'element-plus';
import Catalog from './Catalog.vue';
import ProductImage from './ProductImage.vue';
import ShoppingLinks from './ShoppingLinks.vue';
import UiIcon from './UiIcon.vue';
import {api,categories,labels,priceText,scenarioWeights} from './api';
const props=defineProps({context:Object});const emit=defineEmits(['navigate']);
const podium=['gold','silver','bronze'];
const mode=ref('recommend'),query=ref(props.context.profile.needs),busy=ref(false),showAll=ref(false),detail=ref(null);
const products=computed(()=>props.context.products.filter(p=>p.recommendation_eligible===true&&p.price!=null&&p.price<=props.context.profile.budget&&p.category===props.context.profile.category&&(!props.context.profile.subcategory||p.subcategory===props.context.profile.subcategory)&&(props.context.profile.include_reference!==false||p.recommendation_tier!=='reference')&&(props.context.profile.include_used===true||p.offer?.item_condition!=='used')).sort((a,b)=>b.score-a.score)),visible=computed(()=>showAll.value?products.value:products.value.slice(0,6));
const process=computed(()=>props.context.process||{});
const priorities=computed(()=>Object.entries(props.context.profile.weights||{}).filter(([k,v])=>v>0).sort((a,b)=>b[1]-a[1]).slice(0,3));
function prioritize(metric){props.context.profile.weights={performance:5,price:5,battery:5,portability:5,ease:5,camera:5,screen:5,[metric]:50};recalc()}
const pending=computed(()=>props.context.pendingPrice||[]),overBudget=computed(()=>props.context.overBudget||[]);
const scenarios=[['学生轻薄本','6000元笔记本，用于学习和编程，希望轻便、续航好。'],['长辈手机','2000元手机，给父母用，希望字体大、操作简单、续航好。'],['游戏本','7000元游戏本，用于游戏，希望屏幕和性能好。'],['通勤耳机','2000元耳机，用于通勤，希望降噪好、佩戴舒适。'],['旅行相机','15000元相机，用于旅行摄影，希望轻便。'],['学习平板','3500元平板，用于网课和手写笔记。']];
let serial=0,timer,disposed=false;
async function recalc(){const seq=++serial;busy.value=true;try{const result=await api('recommend',{...props.context.profile,purpose:'recommend'});if(seq!==serial||disposed)return;props.context.products=result.products;props.context.pendingPrice=result.pending_price;props.context.overBudget=result.over_budget;props.context.process=result.process;if(!result.products.some(p=>p.id===props.context.selectedId))props.context.selectedId=result.products[0]?.id;showAll.value=false;props.context.reportDocument=null;}catch(e){if(!disposed)ElMessage.error(e.message)}finally{if(seq===serial)busy.value=false}}
async function analyze(text=query.value){query.value=text;busy.value=true;try{const profile=await api('profile',{text});if(disposed)return;Object.assign(props.context.profile,profile);await recalc()}catch(e){if(!disposed)ElMessage.error(e.message);busy.value=false}}
function inspect(p){props.context.selectedId=p.id;detail.value=p;}
function updateWeights(){clearTimeout(timer);timer=setTimeout(recalc,300)}
function changeScenario(){props.context.profile.weights=scenarioWeights(props.context.profile.scenario);props.context.profile.user_type=props.context.profile.scenario==='老人使用'?'长辈':props.context.profile.scenario==='学习'?'学生':'普通用户';recalc()}
onMounted(recalc);onBeforeUnmount(()=>{disposed=true;serial++;clearTimeout(timer)});
</script>
<template>
<section class="personal-page">
 <div class="page-heading"><div><span class="eyebrow">PERSONAL PICKS</span><h1>每次选择，都更适合你<span class="heading-dot">✦</span></h1><p>告诉我你的预算与生活场景，一起找到值得考虑的数码产品。</p></div><div class="segmented"><button :class="{chosen:mode==='recommend'}" @click="mode='recommend'">需求推荐</button><button :class="{chosen:mode==='catalog'}" @click="mode='catalog'">浏览全部产品</button></div></div>
 <Catalog v-if="mode==='catalog'"/>
 <template v-else>
 <div class="request-panel"><div class="request-label"><span><UiIcon name="spark" :size="17"/> 从你的真实需求出发</span><small>Ctrl + Enter 快速分析</small></div><div class="request-row"><textarea v-model="query" aria-label="购买需求" placeholder="例如：预算6000元，想买一台通勤轻便、适合编程的笔记本……" @keydown.ctrl.enter="analyze()"></textarea><button class="primary-btn" :disabled="busy" @click="analyze()">{{busy?'分析中…':'为我推荐'}} <UiIcon name="arrow" :size="18"/></button></div><div class="scenario-chips"><span>试试</span><button v-for="[name,text] in scenarios" :key="name" @click="analyze(text)">{{name}} ↗</button></div></div>
 <div class="filter-strip"><label>产品类别<el-select v-model="context.profile.category" @change="context.profile.subcategory=null;recalc()"><el-option v-for="c in categories" :key="c" :value="c" :label="c"/></el-select></label><label>预算上限<el-input-number v-model="context.profile.budget" :min="1" :max="50000" :step="100" @change="recalc"/></label><label>主要用途<el-select v-model="context.profile.scenario" @change="changeScenario"><el-option v-for="c in ['学习','办公','游戏','老人使用']" :key="c" :value="c" :label="c"/></el-select></label><div class="profile-hint"><span class="soft-label">{{context.profile.user_type || '日常选购'}} · {{context.profile.subcategory || '不限细分类别'}}</span><small>调整偏好，结果同步更新</small></div></div>
 <details class="preference-details"><summary><UiIcon name="settings" :size="16"/> 调整关注重点 <span>性能、续航、便携与更多</span></summary><div class="weights-grid"><label v-for="(value,key) in context.profile.weights" :key="key"><span>{{labels[key]}} <b>{{value}}</b></span><input type="range" v-model.number="context.profile.weights[key]" min="0" max="50" @input="updateWeights"/></label></div><p class="muted small">按可核对的数值与功能计算参考分，未知参数不填充；相同依据可以同分。</p></details>
 <div class="quote-preferences"><label><input type="checkbox" :checked="context.profile.include_reference!==false" @change="context.profile.include_reference=$event.target.checked;recalc()"/> 参考公开平台报价匹配预算 <small>配置与成色仍需核对</small></label><label><input type="checkbox" :checked="context.profile.include_used===true" @change="context.profile.include_used=$event.target.checked;recalc()"/> 接受二手 / 闲鱼报价 <small>默认优先全新</small></label></div>
 <div class="recommend-process" aria-label="推荐过程"><div><span>01 / 输入需求</span><strong>{{context.profile.category}} · {{context.profile.scenario}}</strong><p>{{context.profile.needs}}</p></div><div><span>02 / 提取条件</span><strong>预算 ≤ ¥{{Number(context.profile.budget).toLocaleString()}}</strong><p>{{context.profile.subcategory||'不限细分类型'}} · {{context.profile.include_used?'接受二手':'优先全新'}}<br>关注 {{priorities.map(([k])=>labels[k]).join('、')}}</p></div><div><span>03 / 筛选候选</span><strong>{{process.filtered_total ?? products.length}} 款 → {{process.eligible ?? products.length}} 款</strong><p>超预算 {{process.over_budget||0}} · 待核价 {{process.pending_price||0}}<br>{{context.profile.curated_only?'在精选资料档案中筛选':'在当前品类资料中筛选'}}</p></div><div><span>04 / 排序与解释</span><strong>{{products.length?'TOP '+Math.min(3,products.length)+' 已生成':'等待有效报价'}}</strong><p>按当前偏好计算参考分<br>每款都可查看参数与价格依据</p></div></div>
 <div class="priority-bar"><span>当前关注</span><b v-for="[key,value] in priorities" :key="key">{{labels[key]}} {{value}}</b><button @click="prioritize('price')">预算优先</button><button @click="prioritize('portability')">轻便优先</button><button @click="prioritize('battery')">续航优先</button><label><input type="checkbox" :checked="context.profile.curated_only===true" @change="context.profile.curated_only=$event.target.checked;recalc()"/>精选资料档案</label></div>
 <div class="section-title"><div><span class="eyebrow">YOUR SHORTLIST</span><h2>预算匹配推荐</h2></div><span class="muted small">{{products.length}} 款 · 按参考分从高到低</span></div>
 <p class="budget-explanation">以采集到的同地区报价匹配 ¥{{Number(context.profile.budget).toLocaleString()}} 预算，优先采用具体配置标价。平台参考价与二手价会单独标明，只有有价格依据且不超过预算的产品参与 TOP 排名。<span v-if="context.profile.scenario==='老人使用'">长辈场景重点看续航、字体与辅助功能、阅读空间；旗舰性能不再持续加分，音量与操作仍需试用。</span></p>
 <div class="recommend-grid" v-loading="busy"><article v-for="(p,index) in visible" :key="p.id" :class="['pick-card',context.selectedId===p.id&&'selected',index<3&&'top-pick-'+podium[index]]"><div class="pick-top"><span v-if="index<3" :class="['podium-badge',podium[index]]" :aria-label="'推荐第'+(index+1)+'名'"><UiIcon name="spark" :size="16"/><span><strong>TOP {{index+1}}</strong><small>推荐第{{index+1}}名</small></span></span><span v-else class="pick-rank">{{String(index+1).padStart(2,'0')}}</span><span class="pick-score">{{p.score.toFixed(2)}}<small>选购参考分</small></span></div><ProductImage :product="p"/><small class="product-meta">{{p.brand}} · {{p.subcategory}}</small><h3>{{p.name}}</h3><p class="pick-description">{{p.description}}</p><div class="price-line"><strong>{{priceText(p)}}</strong><span>{{p.budget_status}}</span></div><p class="quote-proof" v-if="p.offer">{{p.offer.price_type}} · {{p.offer.merchant}}<br>{{p.offer.variant}}<br>采集于 {{new Date(p.offer.observed_at).toLocaleDateString('zh-CN')}} · <a :href="p.offer.source_url" target="_blank" rel="noopener noreferrer">报价凭据 ↗</a></p><ul class="pick-reasons"><li v-for="reason in p.pros.slice(0,2)" :key="reason">{{reason}}</li></ul><div class="confidence-line"><span>评分信息覆盖</span><b>{{p.confidence}}%</b><i><em :style="{width:p.confidence+'%'}"></em></i></div><div class="pick-actions"><button @click="inspect(p)">评分依据</button><button @click="emit('navigate','compare',p)">加入对比</button><button class="accent" @click="emit('navigate','report',p)">生成报告 ↗</button></div><ShoppingLinks :product="p" compact/></article></div>
 <div v-if="!busy&&!products.length" class="budget-empty panel" role="status"><UiIcon name="search" :size="30"/><h3>暂时没有已确认在预算内的配置报价</h3><p>不会把未核价或超预算的产品列为 TOP 推荐。你可以展开下方待核价产品，到平台核对完整配置与实际价格。</p></div><button v-if="products.length>6" class="load-more" @click="showAll=!showAll">{{showAll?'收起更多产品':'查看全部 '+products.length+' 款产品'}} <span>{{showAll?'↑':'↓'}}</span></button>
 <details v-if="pending.length" class="budget-review panel"><summary>待核价产品 <b>{{pending.length}} 款</b><span>尚不能确认符合预算，不参与 TOP 推荐</span></summary><p class="muted small">以下仅供查询。起售价、过期报价或缺少同地区配置报价，都不能证明实际购买价在预算内。</p><div class="quote-check-grid"><article v-for="p in pending" :key="p.id"><small>{{p.brand}} · {{p.subcategory}}</small><h3>{{p.name}}</h3><p>{{p.budget_status}} · {{priceText(p)}}</p><ShoppingLinks :product="p" compact/><div class="quote-check-actions"><button @click="emit('navigate','compare',p)">查看对比</button><button @click="emit('navigate','report',p)">了解选购注意事项 ↗</button></div></article></div></details>
 <details v-if="overBudget.length" class="budget-review panel"><summary>超出预算的产品 <b>{{overBudget.length}} 款</b><span>已排除推荐</span></summary><div class="quote-check-grid"><article v-for="p in overBudget" :key="p.id"><small>{{p.brand}} · {{p.subcategory}}</small><h3>{{p.name}}</h3><p>{{priceText(p)}} · 比预算至少多 ¥{{Math.ceil(p.price-context.profile.budget).toLocaleString()}}</p><button class="text-btn" @click="emit('navigate','compare',p)">仍想了解，查看对比 ↗</button></article></div></details>
 <p class="page-footnote">参考分结合可核对参数与场景计算；缺失资料不获加分。具体配置、地区及官网测试条件请在下单前核对。</p>
 </template>
 <el-dialog :model-value="!!detail" @close="detail=null" :title="detail?.name" width="min(800px,94vw)"><template v-if="detail"><p class="muted">选购参考分 {{detail.score}} · 评分信息覆盖 {{detail.confidence}}%</p><div class="basis-list"><div v-for="(item,key) in detail.metric_details" :key="key"><span>{{labels[key]}}</span><strong>{{detail.metrics[key]}}</strong><p>{{item.basis}}</p><small>{{item.rule}}</small><a :href="item.source_url" target="_blank" rel="noopener noreferrer">官方依据 ↗</a></div></div><p class="page-footnote">{{detail.score_note}}</p><ShoppingLinks :product="detail"/></template></el-dialog>
</section>
</template>
<style scoped>
.quote-preferences{display:flex;flex-wrap:wrap;gap:12px 26px;margin:20px 0 30px;color:#64677e;font-size:12px}.quote-preferences label{display:flex;align-items:center;gap:7px;cursor:pointer}.quote-preferences input{accent-color:#7662e8}.quote-preferences small{color:#a0a2b3;font-size:10px}
.budget-explanation{color:#72768b;font-size:13px;line-height:1.9;margin:-7px 0 22px}.budget-explanation span{display:block;color:#7662c4}.budget-empty{text-align:center;padding:32px 24px;margin:12px 0 24px;color:#77798d}.budget-empty h3{color:#32334c;margin:14px 0 8px}.budget-empty p{font-size:13px;line-height:1.9;max-width:580px;margin:0 auto}.budget-review{padding:20px 24px;margin:22px 0}.budget-review summary{cursor:pointer;color:#35364c;font-weight:600;line-height:1.8}.budget-review summary b{font-size:12px;color:#7866cc;background:#f3f0ff;border-radius:5px;padding:4px 8px;margin-left:8px}.budget-review summary span{font-weight:400;color:#8c8fa1;font-size:12px;margin-left:15px}.quote-check-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-top:18px}.quote-check-grid article{border:1px solid #ebebf4;border-radius:12px;padding:20px;background:#fdfdff;min-width:0}.quote-check-grid small{color:#9396aa}.quote-check-grid h3{font-size:16px;margin:10px 0;color:#35364c}.quote-check-grid p{color:#8d7b59;font-size:12px;line-height:1.8}.quote-check-actions{display:flex;flex-wrap:wrap;gap:14px;margin-top:14px}.quote-check-actions button{font-size:12px;color:#7864d2;background:none;border:0;cursor:pointer;padding:0}@media(max-width:1100px){.quote-check-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.quote-check-grid{grid-template-columns:1fr}.budget-review summary span{display:block;margin-left:0}}
</style>
